#ifndef STDLIB_LAPACK_BASE_DPBTF2_PRIVATE_H
#define STDLIB_LAPACK_BASE_DPBTF2_PRIVATE_H

#include "stdlib/lapack/base/shared.h"
#include "stdlib/blas/base/dscal.h"
#include <limits.h>
#include <stddef.h>
#include <stdint.h>

typedef char dpbtf2_lapack_integer_check[ ( sizeof( LAPACK_INT ) <= sizeof( intmax_t ) && (LAPACK_INT)-1 < 0 ) ? 1 : -1 ];
typedef char dpbtf2_blas_integer_check[ ( sizeof( CBLAS_INT ) <= sizeof( intmax_t ) && (CBLAS_INT)-1 < 0 ) ? 1 : -1 ];

/**
* Returns the largest configured LAPACK integer.
*/
static inline intmax_t dpbtf2_lapack_max( void ) {
	return (intmax_t)( UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( LAPACK_INT ))*CHAR_BIT + 1 ) );
}

/**
* Returns the largest independently configured BLAS integer.
*/
static inline uintmax_t dpbtf2_blas_max( void ) {
	return UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( CBLAS_INT ))*CHAR_BIT + 1 );
}

/**
* Computes a magnitude without negating a minimum signed integer.
*/
static inline uintmax_t dpbtf2_magnitude( const intmax_t value ) {
	return value < 0 ? (uintmax_t)( -(value+1) )+1 : (uintmax_t)value;
}

/**
* Computes the greatest common divisor of two nonzero magnitudes.
*/
static inline uintmax_t dpbtf2_gcd( uintmax_t x, uintmax_t y ) {
	uintmax_t remainder;
	while ( y != 0 ) {
		remainder = x%y;
		x = y;
		y = remainder;
	}
	return x;
}

/**
* Validates scalar metadata, including KD+1 even on an empty call.
*/
static inline LAPACK_INT dpbtf2_dimensions( const int main, const LAPACK_UPLO uplo, const LAPACK_INT N, const LAPACK_INT KD ) {
	if ( uplo != LAPACK_UPPER_TRIANGLE && uplo != LAPACK_LOWER_TRIANGLE ) return main ? -2 : -1;
	if ( N < 0 ) return main ? -3 : -2;
	if ( KD < 0 || KD == dpbtf2_lapack_max() ) return main ? -4 : -3;
	return 0;
}

/**
* Checks full configured view products, sequential endpoints and injectivity.
*
* No array pointer is accessed. Errors identify row/column/offset at
* ndarray positions -5/-6/-7. Minimum used strides are conservatively
* rejected before multiplication. Unused singleton strides are ignored.
*/
static inline LAPACK_INT dpbtf2_geometry( const intmax_t rows, const intmax_t columns, const intmax_t stride1, const intmax_t stride2, const intmax_t offset, intmax_t *first, intmax_t *last ) {
	const intmax_t limit = dpbtf2_lapack_max();
	uintmax_t divisor;
	intmax_t delta1;
	intmax_t delta2;
	intmax_t lo;
	intmax_t hi;

	if ( rows <= 0 || columns <= 0 || offset < 0 || offset > limit ) return -7;
	if ( rows > 1 && ( stride1 == 0 || dpbtf2_magnitude( stride1 ) > (uintmax_t)limit/(uintmax_t)(rows-1) ) ) return -5;
	if ( columns > 1 && ( stride2 == 0 || dpbtf2_magnitude( stride2 ) > (uintmax_t)limit/(uintmax_t)(columns-1) ) ) return -6;
	if ( rows > 1 && columns > 1 ) {
		divisor = dpbtf2_gcd( dpbtf2_magnitude( stride1 ), dpbtf2_magnitude( stride2 ) );
		if ( dpbtf2_magnitude( stride2 )/divisor < (uintmax_t)rows && dpbtf2_magnitude( stride1 )/divisor < (uintmax_t)columns ) return -6;
	}
	delta1 = rows > 1 ? (rows-1)*stride1 : 0;
	delta2 = columns > 1 ? (columns-1)*stride2 : 0;
	if ( ( delta1 < 0 && offset < -delta1 ) || ( delta1 >= 0 && offset > limit-delta1 ) ) return -7;
	lo = offset+( delta1 < 0 ? delta1 : 0 );
	hi = offset+( delta1 > 0 ? delta1 : 0 );
	if ( ( delta2 < 0 && lo < -delta2 ) || ( delta2 >= 0 && hi > limit-delta2 ) ) return -7;
	lo += delta2 < 0 ? delta2 : 0;
	hi += delta2 > 0 ? delta2 : 0;
	*first = lo;
	*last = hi;
	return 0;
}

/**
* Checks the physical double envelope without forming a derived pointer.
*
* Capacity and hidden physical aliases remain caller preconditions.
*/
static inline int dpbtf2_envelope_valid( const double *data, const intmax_t first, const intmax_t last ) {
	const uintptr_t address = (uintptr_t)data;
	const size_t size = sizeof( double );
	uintmax_t end;

	if ( data == NULL || address%size != 0 || first < 0 || last < first ) return 0;
	if ( size-1 > (uintmax_t)PTRDIFF_MAX || (uintmax_t)last > ( (uintmax_t)PTRDIFF_MAX-(size-1) )/size ) return 0;
	end = (uintmax_t)last*size+(size-1);
	return end <= UINTPTR_MAX && address <= UINTPTR_MAX-(uintptr_t)end;
}

/**
* Checks conservative unchanged Fortran DSCAL trips without overflow.
*
* Count0 skips dispatch. Count1 uses normalized stride1. Unit unrolled
* loops require count+5 to fit; nonunit loops require count<=MAX-2 and
* count*abs(stride)+abs(stride)+1<=MAX. The gate is data independent.
*/
static inline int dpbtf2_blas_valid( const intmax_t count, const intmax_t stride ) {
	const uintmax_t limit = dpbtf2_blas_max();
	uintmax_t length;
	uintmax_t magnitude;

	if ( count < 0 ) return 0;
	if ( count <= 1 ) return 1;
	length = (uintmax_t)count;
	magnitude = dpbtf2_magnitude( stride );
	if ( length > limit || magnitude == 0 || magnitude > limit ) return 0;
	if ( magnitude == 1 ) return length < 5 || length <= limit-5;
	if ( length > limit-2 || length > (limit-1)/magnitude ) return 0;
	return length*magnitude <= limit-magnitude-1;
}

/**
* Checks the selected maximum helper count and stride before mutation.
*/
static inline LAPACK_INT dpbtf2_helpers_valid( const LAPACK_UPLO uplo, const intmax_t N, const intmax_t KD, const intmax_t stride1, const intmax_t stride2 ) {
	const intmax_t limit = dpbtf2_lapack_max();
	const intmax_t minimum = -limit-1;
	const intmax_t count = KD < N-1 ? KD : N-1;
	intmax_t stride;

	if ( count <= 1 ) return 0;
	if ( uplo == LAPACK_UPPER_TRIANGLE ) {
		if ( ( stride1 > 0 && stride2 < minimum+stride1 ) || ( stride1 < 0 && stride2 > limit+stride1 ) ) return -6;
		stride = stride2-stride1;
		if ( dpbtf2_magnitude( stride ) > (uintmax_t)limit ) return -6;
	} else {
		stride = stride1;
	}
	return dpbtf2_blas_valid( count, stride ) ? 0 : ( uplo == LAPACK_UPPER_TRIANGLE ? -6 : -5 );
}

/**
* Validates all ndarray metadata and selected helpers before any write.
*/
static inline LAPACK_INT dpbtf2_validate( const LAPACK_UPLO uplo, const LAPACK_INT N, const LAPACK_INT KD, const double *AB, const LAPACK_INT strideAB1, const LAPACK_INT strideAB2, const LAPACK_INT offsetAB ) {
	intmax_t first;
	intmax_t last;
	LAPACK_INT info;

	info = dpbtf2_dimensions( 0, uplo, N, KD );
	if ( info != 0 || N == 0 ) return info;
	if ( N == dpbtf2_lapack_max() ) return -2;
	info = dpbtf2_geometry( (intmax_t)KD+1, N, strideAB1, strideAB2, offsetAB, &first, &last );
	if ( info != 0 ) return info;
	info = dpbtf2_helpers_valid( uplo, N, KD, strideAB1, strideAB2 );
	if ( info != 0 ) return info;
	if ( !dpbtf2_envelope_valid( AB, first, last ) ) return -4;
	return 0;
}

/**
* Computes a fully prevalidated band's zero-based cell index.
*/
static inline intmax_t dpbtf2_index( const intmax_t row, const intmax_t column, const intmax_t stride1, const intmax_t stride2, const intmax_t offset ) {
	return offset+row*stride1+column*stride2;
}

/**
* Applies the fixed-alpha=-1 update in original logical DSYR order.
*
* Only the original outer X-zero skip is retained. A volatile product
* keeps the multiplication rounded before addition under contraction.
* Subtract KD-q before adding i to avoid a canceled KD+i transient.
*/
static inline void dpbtf2_rank( const LAPACK_UPLO uplo, const intmax_t KD, const intmax_t step, const intmax_t count, double *AB, const intmax_t stride1, const intmax_t stride2, const intmax_t offset ) {
	intmax_t q;
	intmax_t i;
	intmax_t index;
	intmax_t xindex;
	double x;
	double temp;
	volatile double product;

	for ( q = 0; q < count; q++ ) {
		xindex = uplo == LAPACK_UPPER_TRIANGLE ? dpbtf2_index( KD-1-q, step+1+q, stride1, stride2, offset ) : dpbtf2_index( 1+q, step, stride1, stride2, offset );
		x = AB[ xindex ];
		if ( x != 0.0 ) {
			temp = -1.0*x;
			if ( uplo == LAPACK_UPPER_TRIANGLE ) {
				for ( i = 0; i <= q; i++ ) {
					index = dpbtf2_index( KD-q+i, step+1+q, stride1, stride2, offset );
					product = AB[ dpbtf2_index( KD-1-i, step+1+i, stride1, stride2, offset ) ]*temp;
					AB[ index ] += product;
				}
			} else {
				for ( i = q; i < count; i++ ) {
					index = dpbtf2_index( i-q, step+1+q, stride1, stride2, offset );
					product = AB[ dpbtf2_index( 1+i, step, stride1, stride2, offset ) ]*temp;
					AB[ index ] += product;
				}
			}
		}
	}
}

#endif // !STDLIB_LAPACK_BASE_DPBTF2_PRIVATE_H
